import { z } from "zod";

const isoDate = (message: string) =>
  z.string().refine((val) => !isNaN(Date.parse(val)), { message });

/** Staff-entered bank / transfer reference. Never generated by the system. */
const disbursementReference = z
  .string()
  .trim()
  .min(3, "Disbursement reference/UTR required")
  .max(100)
  .regex(
    /^[A-Za-z0-9][A-Za-z0-9 ./_-]*$/,
    "Reference may contain letters, digits, spaces, '.', '/', '_' and '-'"
  );

const optionalNotes = z.string().trim().max(1000).optional().nullable();

export const PayrollPeriodIdSchema = z.string().uuid("Invalid period ID");

export const CreatePayrollPeriodSchema = z.object({
  code: z
    .string()
    .trim()
    .min(4, "Period code required (e.g. 2026-04)")
    .max(20)
    .regex(/^[A-Za-z0-9._-]+$/, "Period code may contain letters, digits, '.', '_' and '-'"),
  startDate: isoDate("Valid ISO date required for start date"),
  endDate: isoDate("Valid ISO date required for end date"),
  notes: optionalNotes,
});

export const RecordDisbursementSchema = z.object({
  payrollRecordId: z.string().uuid("Invalid payroll record ID"),
  disbursementReference,
  notes: optionalNotes,
});

/**
 * Manual period transitions. PAID is never set manually: a period becomes PAID only
 * when every enrolled record has a recorded disbursement.
 */
export const UpdatePayrollPeriodStatusSchema = z.object({
  periodId: PayrollPeriodIdSchema,
  status: z.enum(["DRAFT", "FINALIZED", "VOID"]),
  notes: optionalNotes,
});

export const BulkDisbursementSchema = z.object({
  periodId: PayrollPeriodIdSchema,
  disbursementReference,
  notes: optionalNotes,
});

/**
 * Optional text field: `undefined` keeps the stored value, `null` or an empty string clears it.
 */
const clearableText = (max: number) =>
  z
    .string()
    .trim()
    .max(max)
    .transform((val): string | null => (val === "" ? null : val))
    .nullable()
    .optional();

/** Alphanumeric identifier (spaces ignored). `undefined` keeps, `null`/"" clears. */
const clearableIdentifier = (min: number, max: number, label: string) =>
  z
    .string()
    .transform((val) => val.replace(/\s+/g, "").toUpperCase())
    .pipe(
      z.union([
        z.literal(""),
        z
          .string()
          .min(min, `${label} must be at least ${min} characters`)
          .max(max, `${label} must be at most ${max} characters`)
          .regex(/^[A-Z0-9]+$/, `${label} may only contain letters and digits`),
      ])
    )
    .transform((val): string | null => (val === "" ? null : val))
    .nullable()
    .optional();

export const UpdateEmployeePayoutProfileSchema = z.object({
  employeeId: z.string().uuid("Invalid employee ID"),
  isPaid: z.boolean(),
  employmentType: z.enum(["INTERN", "FULL_TIME"]).nullable().optional(),
  stipendAmount: z.number().finite().min(0).max(100000000).nullable().optional(),
  bankName: clearableText(100),
  accountNumber: clearableIdentifier(6, 34, "Account number"),
  ifscCode: clearableIdentifier(4, 20, "IFSC code"),
  accountHolderName: clearableText(100),
  panNumber: clearableIdentifier(6, 20, "PAN"),
});

export const GeneratePayrollRecordsSchema = z.object({
  periodId: PayrollPeriodIdSchema,
});

export type CreatePayrollPeriodInput = z.input<typeof CreatePayrollPeriodSchema>;
export type RecordDisbursementInput = z.input<typeof RecordDisbursementSchema>;
export type UpdatePayrollPeriodStatusInput = z.input<typeof UpdatePayrollPeriodStatusSchema>;
export type BulkDisbursementInput = z.input<typeof BulkDisbursementSchema>;
export type UpdateEmployeePayoutProfileInput = z.input<typeof UpdateEmployeePayoutProfileSchema>;
export type GeneratePayrollRecordsInput = z.input<typeof GeneratePayrollRecordsSchema>;

export type CreatePayrollPeriodData = z.output<typeof CreatePayrollPeriodSchema>;
export type RecordDisbursementData = z.output<typeof RecordDisbursementSchema>;
export type UpdatePayrollPeriodStatusData = z.output<typeof UpdatePayrollPeriodStatusSchema>;
export type BulkDisbursementData = z.output<typeof BulkDisbursementSchema>;
export type UpdateEmployeePayoutProfileData = z.output<typeof UpdateEmployeePayoutProfileSchema>;
